//! Support for the code generated by `MssqlLoad`.
//!
//! The generated load is written against `dyn LoadSink<E>` so it is compiled once per entity
//! instead of once per entity and collection, and the code generic over the collection lives
//! here so it is borrow checked once.

use crate::{
    FilterSql, MssqlMeta, MssqlProvider, ToSql,
    metrics_helper::load_wrap,
    mssql_provider::{ROW_BATCH, RowSink},
};
use std::borrow::Cow;
use storm::{
    BoxFuture, Entity, GetMut, Result,
    provider::{LoadArgs, LoadOneInternal, ProviderContainer},
};
use tiberius::Row;

/// Implemented by `MssqlLoad`: loads the entities in a collection erased behind [Self::Sink].
///
/// Returns a `BoxFuture` rather than `impl Future`: inferring and checking an opaque type per
/// entity costs more compile time than the allocation costs at runtime.
#[doc(hidden)]
pub trait MssqlLoadEntity: Entity + MssqlMeta {
    /// `dyn LoadSink<Self>` or `dyn TranslatedLoadSink<Self>`.
    type Sink: ?Sized + Send;

    fn load_into<'a, 'm>(
        provider: &'a ProviderContainer,
        sql: Cow<'a, str>,
        params: Cow<'a, [&'a dyn ToSql]>,
        args: LoadArgs,
        sink: &'m mut Self::Sink,
    ) -> BoxFuture<'m, Result<()>>
    where
        'a: 'm;
}

/// Converts a collection to the [MssqlLoadEntity::Sink] of the entity.
#[doc(hidden)]
pub trait AsLoadSink<S: ?Sized> {
    fn as_load_sink(&mut self) -> &mut S;
}

impl<E, C> AsLoadSink<dyn LoadSink<E> + 'static> for C
where
    E: Entity,
    C: LoadSink<E> + 'static,
{
    #[inline]
    fn as_load_sink(&mut self) -> &mut (dyn LoadSink<E> + 'static) {
        self
    }
}

impl<E, C> AsLoadSink<dyn TranslatedLoadSink<E> + 'static> for C
where
    E: Entity,
    C: TranslatedLoadSink<E> + 'static,
{
    #[inline]
    fn as_load_sink(&mut self) -> &mut (dyn TranslatedLoadSink<E> + 'static) {
        self
    }
}

/// `LoadAll::load_all_with_args` of `MssqlLoad`.
///
/// Defined here so the part generic over the collection is borrow checked once instead of
/// once per entity.
#[doc(hidden)]
pub fn _load_all<'a, E, C, F>(
    container: &'a ProviderContainer,
    provider: &str,
    filter: &'a F,
    args: LoadArgs,
) -> BoxFuture<'a, Result<C>>
where
    E: MssqlLoadEntity,
    C: AsLoadSink<E::Sink> + Default + Send + 'a,
    F: FilterSql,
{
    if container.is_noop(provider) {
        return Box::pin(async { Ok(C::default()) });
    }

    let (sql, params) = filter.filter_sql(0);

    load_wrap(
        async move {
            let mut map = C::default();
            E::load_into(container, sql, params, args, map.as_load_sink()).await?;
            Ok(map)
        },
        E::TABLE,
    )
}

/// `LoadOne::load_one_with_args` of `MssqlLoad`.
#[doc(hidden)]
pub fn _load_one<'a, E, const N: usize>(
    container: &'a ProviderContainer,
    provider: &str,
    sql: &'static str,
    params: [&'a dyn ToSql; N],
    args: LoadArgs,
) -> BoxFuture<'a, Result<Option<E>>>
where
    E: MssqlLoadEntity,
    LoadOneInternal<E>: AsLoadSink<E::Sink>,
{
    if container.is_noop(provider) {
        return Box::pin(async { Ok(None) });
    }

    load_wrap(
        async move {
            let mut v = LoadOneInternal::<E>::default();
            let params = Cow::Borrowed(&params[..]);
            E::load_into(
                container,
                Cow::Borrowed(sql),
                params,
                args,
                v.as_load_sink(),
            )
            .await?;
            Ok(v.into_inner())
        },
        E::TABLE,
    )
}

/// Collection receiving the entities loaded by `MssqlLoad`.
#[doc(hidden)]
pub trait LoadSink<E: Entity>: Send {
    fn extend_rows(&mut self, rows: &mut Vec<(E::Key, E)>);

    /// Drops the loaded entities before the query is retried.
    fn reset(&mut self);
}

impl<E, C> LoadSink<E> for C
where
    E: Entity,
    C: Default + Extend<(E::Key, E)> + Send,
{
    #[inline]
    fn extend_rows(&mut self, rows: &mut Vec<(E::Key, E)>) {
        self.extend(rows.drain(..));
    }

    #[inline]
    fn reset(&mut self) {
        *self = C::default();
    }
}

/// [LoadSink] of an entity with translated fields, filled by a second query.
#[doc(hidden)]
pub trait TranslatedLoadSink<E: Entity>: LoadSink<E> {
    fn get_mut(&mut self, k: &E::Key) -> Option<&mut E>;
}

impl<E, C> TranslatedLoadSink<E> for C
where
    E: Entity,
    C: LoadSink<E> + GetMut<E>,
{
    #[inline]
    fn get_mut(&mut self, k: &E::Key) -> Option<&mut E> {
        GetMut::get_mut(self, k)
    }
}

/// Loads the rows mapped by `mapper` in `sink`, in batches.
#[doc(hidden)]
pub async fn _load_rows<E, M, S>(
    provider: &MssqlProvider,
    sql: &str,
    params: &[&dyn ToSql],
    mapper: M,
    use_transaction: bool,
    sink: &mut S,
) -> Result<()>
where
    E: Entity,
    M: FnMut(Row) -> Result<(E::Key, E)> + Send,
    S: LoadSink<E> + ?Sized,
{
    let mut rows = LoadRows {
        mapper,
        rows: Vec::with_capacity(ROW_BATCH),
        sink,
    };

    provider
        .query_rows_dyn(sql, params, use_transaction, &mut rows)
        .await
}

/// Calls `f` for each row.
#[doc(hidden)]
pub async fn _query_rows_each(
    provider: &MssqlProvider,
    sql: &str,
    params: &[&dyn ToSql],
    use_transaction: bool,
    f: &mut (dyn FnMut(Row) -> Result<()> + Send),
) -> Result<()> {
    provider
        .query_rows_dyn(sql, params, use_transaction, &mut Each(f))
        .await
}

struct LoadRows<'s, E: Entity, M, S: ?Sized> {
    mapper: M,
    rows: Vec<(E::Key, E)>,
    sink: &'s mut S,
}

impl<E, M, S> RowSink for LoadRows<'_, E, M, S>
where
    E: Entity,
    M: FnMut(Row) -> Result<(E::Key, E)> + Send,
    S: LoadSink<E> + ?Sized,
{
    fn row(&mut self, row: Row) -> Result<()> {
        self.rows.push((self.mapper)(row)?);

        if self.rows.len() == ROW_BATCH {
            self.sink.extend_rows(&mut self.rows);
        }

        Ok(())
    }

    fn end(&mut self) {
        if !self.rows.is_empty() {
            self.sink.extend_rows(&mut self.rows);
        }
    }

    fn reset(&mut self) {
        self.rows.clear();
        self.sink.reset();
    }
}

struct Each<'f>(&'f mut (dyn FnMut(Row) -> Result<()> + Send));

impl RowSink for Each<'_> {
    fn row(&mut self, row: Row) -> Result<()> {
        (self.0)(row)
    }

    fn end(&mut self) {}

    fn reset(&mut self) {}
}
